<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login(); $user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??''; $isi=trim($_POST['isi']??''); if($action==='topik' && trim($_POST['judul']??'')!=='' && $isi!==''){ $pdo->prepare('INSERT INTO forum_topik (user_id,judul,isi) VALUES (?,?,?)')->execute([$user['id'],trim($_POST['judul']),$isi]); } if($action==='balas' && $isi!=='' && (int)$_POST['topik_id']) $pdo->prepare('INSERT INTO forum_balasan (topik_id,user_id,isi) VALUES (?,?,?)')->execute([(int)$_POST['topik_id'],$user['id'],$isi]); header('Location: forum.php');exit; }
$topics=$pdo->query("SELECT f.*,u.name,u.role,(SELECT COUNT(*) FROM forum_balasan b WHERE b.topik_id=f.id) balasan FROM forum_topik f JOIN users u ON u.id=f.user_id ORDER BY f.created_at DESC")->fetchAll(); $activeTab='forum';$pageTitle='Forum Kelas';require __DIR__.'/includes/header.php'; if($user['role']==='siswa') require __DIR__.'/includes/sidebar_siswa.php'; else echo '<div class="dash-layout"><div class="sidebar"><a class="side-link" href="guru/dashboard.php">← Dashboard Guru</a></div><div class="dash-main">'; ?>
<div class="dash-head"><div><h2>Forum kelas 💬</h2><p>Ajukan pertanyaan, tanggapi dengan santun, dan belajar bersama.</p></div></div><form class="panel forum-compose" method="post"><input type="hidden" name="action" value="topik"><input name="judul" required placeholder="Apa yang ingin kamu diskusikan?"><textarea name="isi" required placeholder="Tulis pertanyaan atau pendapatmu..."></textarea><button class="btn btn-primary btn-sm">Kirim topik</button></form>
<?php foreach($topics as $t): ?><article class="forum-post"><div class="avatar"><?= h(strtoupper(substr($t['name'],0,1))) ?></div><div class="forum-content"><h3><?= h($t['judul']) ?></h3><div class="post-meta"><?= h($t['name']) ?> · <?= h($t['created_at']) ?> · <?= $t['balasan'] ?> balasan</div><p><?= nl2br(h($t['isi'])) ?></p><form method="post" class="reply-form"><input type="hidden" name="action" value="balas"><input type="hidden" name="topik_id" value="<?= $t['id'] ?>"><input name="isi" required placeholder="Tulis tanggapan yang baik..."><button class="btn btn-ghost btn-sm">Balas</button></form></div></article><?php endforeach; ?></div></div><?php require __DIR__.'/includes/footer.php'; ?>
